11	#ifndef CATLASS_GEMM_KERNEL_QUANT_MATMUL_HPP
12	#define CATLASS_GEMM_KERNEL_QUANT_MATMUL_HPP
13	
14	#include "catlass/catlass.hpp"
15	#include "catlass/arch/cross_core_sync.hpp"
16	#include "catlass/arch/resource.hpp"
17	#include "catlass/coord.hpp"
18	#include "catlass/layout/layout.hpp"
19	#include "catlass/detail/callback.hpp"
20	#include "catlass/gemm_coord.hpp"
21	#include "catlass/matrix_coord.hpp"
22	
23	namespace Catlass::Gemm::Kernel {
24	
25	template <class BlockMmad_, class BlockEpilogue_, class BlockScheduler_>
26	class QuantMatmul {
27	public:
28	    using BlockMmad = BlockMmad_;
29	    using ArchTag = typename BlockMmad::ArchTag;
30	    using L1TileShape = typename BlockMmad::L1TileShape;
31	    using ElementA = typename BlockMmad::ElementA;
32	    using LayoutA = typename BlockMmad::LayoutA;
33	    using ElementB = typename BlockMmad::ElementB;
34	    using LayoutB = typename BlockMmad::LayoutB;
35	    using ElementC = typename BlockMmad::ElementC;
36	    using LayoutC = typename BlockMmad::LayoutC;
37	    using ElementAccumulator = typename BlockMmad::ElementAccumulator;
38	
39	    using BlockEpilogue = BlockEpilogue_;
40	    using ElementScale = typename BlockEpilogue::ElementScale;
41	    using LayoutScale = typename BlockEpilogue::LayoutScale;
42	    using ElementPerTokenScale = typename BlockEpilogue::ElementPerTokenScale;
43	    using LayoutPerTokenScale = typename BlockEpilogue::LayoutPerTokenScale;
44	    using ElementD = typename BlockEpilogue::ElementD;
45	    using LayoutD = typename BlockEpilogue::LayoutD;
46	    using EpilogueParams = typename BlockEpilogue::Params;
47	
48	    using BlockScheduler = BlockScheduler_;
49	
50	    friend class AicFinishSync;
51	    friend class AivWaitSync;
52	
53	    struct AicFinishSync {
54	        using MatmulKernel = QuantMatmul<BlockMmad, BlockEpilogue, BlockScheduler>;
55	
56	        CATLASS_DEVICE
57	        void operator()() const
58	        {
59	            Arch::CrossCoreSetFlagWithReverse<0x2, PIPE_FIX>(ptr->flagAicFinishStore);
60	        }
61	
62	        MatmulKernel* ptr;
63	    };
64	
65	    struct AivWaitSync {
66	        using MatmulKernel = QuantMatmul<BlockMmad, BlockEpilogue, BlockScheduler>;
67	
68	        CATLASS_DEVICE
69	        void operator()() const
70	        {
71	            Arch::CrossCoreWaitFlagWithReverse<0x2, PIPE_MTE3>(ptr->flagAicFinishStore);
72	        }
73	
74	        MatmulKernel* ptr;
75	    };
76	
77	    /// Parameters structure
78	    struct Params {
79	        // Data members
80	        GemmCoord problemShape;
81	        __gm__ ElementA* ptrA;
82	        LayoutA layoutA;
83	        __gm__ ElementB* ptrB;
84	        LayoutB layoutB;
85	        __gm__ ElementScale* ptrScale;
86	        LayoutScale layoutScale;
87	        __gm__ ElementPerTokenScale* ptrPerTokenScale;
88	        LayoutPerTokenScale layoutPerTokenScale;
89	        __gm__ ElementD* ptrD;
90	        LayoutD layoutD;
91	        GM_ADDR ptrWorkspace;
92	
93	        // Methods
94	        CATLASS_DEVICE
95	        Params()
96	        {}
97	
98	        CATLASS_DEVICE
99	        Params(
100	            GemmCoord problemShape_, GM_ADDR ptrA_, LayoutA layoutA_, GM_ADDR ptrB_, LayoutB layoutB_,
101	            GM_ADDR ptrScale_, LayoutScale layoutScale_, GM_ADDR ptrPerTokenScale_,
102	            LayoutPerTokenScale layoutPerTokenScale_, GM_ADDR ptrD_, LayoutD layoutD_, GM_ADDR ptrWorkspace_)
103	            : problemShape(problemShape_),
104	              ptrA(reinterpret_cast<__gm__ ElementA*>(ptrA_)),
105	              layoutA(layoutA_),
106	              ptrB(reinterpret_cast<__gm__ ElementB*>(ptrB_)),
107	              layoutB(layoutB_),
108	              ptrScale(reinterpret_cast<__gm__ ElementScale*>(ptrScale_)),
109	              layoutScale(layoutScale_),
110	              ptrPerTokenScale(reinterpret_cast<__gm__ ElementPerTokenScale*>(ptrPerTokenScale_)),
111	              layoutPerTokenScale(layoutPerTokenScale_),
112	              ptrD(reinterpret_cast<__gm__ ElementD*>(ptrD_)),
113	              layoutD(layoutD_),
114	              ptrWorkspace(ptrWorkspace_)
115	        {}
116	    };
117	
118	    // Methods
119	    CATLASS_DEVICE
120	    QuantMatmul()
121	    {}
122	
123	    template <int32_t CORE_TYPE = g_coreType>
124	    CATLASS_DEVICE void operator()(Params const& params);
125	
126	    /// Executes matmul
127	    template <>
128	    CATLASS_DEVICE void operator()<AscendC::AIC>(Params const& params)
129	    {
130	        BlockScheduler blockScheduler;
131	        blockScheduler.Update(params.problemShape, MakeCoord(L1TileShape::M, L1TileShape::N));
132	        uint32_t coreLoops = blockScheduler.GetCoreLoops();
133	
134	        BlockMmad blockMmad(resource);
135	
136	        // Represent the full gm
137	        AscendC::GlobalTensor<ElementA> gmA;
138	        gmA.SetGlobalBuffer(params.ptrA);
139	        AscendC::GlobalTensor<ElementB> gmB;
140	        gmB.SetGlobalBuffer(params.ptrB);
141	        AscendC::GlobalTensor<ElementC> gmC;
142	        gmC.SetGlobalBuffer(reinterpret_cast<__gm__ ElementC*>(params.ptrWorkspace));
143	        layout::RowMajor layoutC(params.problemShape.m(), params.problemShape.n());
144	
145	        uint32_t coreIdx = AscendC::GetBlockIdx();
146	        uint32_t coreNum = AscendC::GetBlockNum();
147	
148	        AicFinishSync aicFinishSync{this};
149	
150	        for (uint32_t loopIdx = coreIdx; loopIdx < coreLoops; loopIdx += coreNum) {
151	            // Compute block location
152	            GemmCoord blockCoord = blockScheduler.GetBlockCoord(loopIdx);
153	            GemmCoord actualBlockShape = blockScheduler.GetActualBlockShape(blockCoord);
154	
155	            // Compute initial location in logical coordinates
156	            MatrixCoord offsetA{blockCoord.m() * L1TileShape::M, blockCoord.k() * L1TileShape::K};
157	            MatrixCoord offsetB{blockCoord.k() * L1TileShape::K, blockCoord.n() * L1TileShape::N};
158	            MatrixCoord offsetC{blockCoord.m() * L1TileShape::M, blockCoord.n() * L1TileShape::N};
159	            int64_t gmOffsetA = params.layoutA.GetOffset(offsetA);
160	            int64_t gmOffsetB = params.layoutB.GetOffset(offsetB);
161	            int64_t gmOffsetC = layoutC.GetOffset(offsetC);
162	
163	            // Compute block-scoped matrix multiply-add
164	            if constexpr (BlockMmad::DispatchPolicy::ASYNC) {
165	                blockMmad(
166	                    gmA[gmOffsetA], params.layoutA, gmB[gmOffsetB], params.layoutB, gmC[gmOffsetC], layoutC,
167	                    actualBlockShape, MakeCallback(&aicFinishSync));
168	            } else {
169	                blockMmad(
170	                    gmA[gmOffsetA], params.layoutA, gmB[gmOffsetB], params.layoutB, gmC[gmOffsetC], layoutC,
171	                    actualBlockShape);
172	                aicFinishSync();
173	            }
174	        }
175	
176	        if constexpr (BlockMmad::DispatchPolicy::ASYNC) {
177	            blockMmad.SynchronizeBlock();
178	        }
179	
180	        AscendC::PipeBarrier<PIPE_ALL>();
181	    }
182	
183	    template <>
184	    CATLASS_DEVICE void operator()<AscendC::AIV>(Params const& params)
185	    {
186	        BlockScheduler blockScheduler;
187	        BlockEpilogue blockEpilogue(resource);
188	
189	        uint32_t coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
190	        uint32_t coreNum = AscendC::GetBlockNum();
191	        uint32_t subCoreIndex = AscendC::GetSubBlockIdx();
192	
193	        AscendC::GlobalTensor<ElementC> gmC;
194	        gmC.SetGlobalBuffer(reinterpret_cast<__gm__ ElementC*>(params.ptrWorkspace));
195	
196	        AivWaitSync aicFinishSync{this};
197	
198	        LayoutC layoutC = LayoutC(params.problemShape.m(), params.problemShape.n());
199	        LayoutScale layoutScale = params.layoutScale;
200	        LayoutPerTokenScale layoutPerTokenScale =
201	            params.layoutPerTokenScale.GetTileLayout(params.problemShape.template GetCoordByAxis<0>());
202	        LayoutD layoutD = params.layoutD.GetTileLayout(params.problemShape.GetCoordMN());
203	
204	        EpilogueParams epilogueParams{params.ptrScale,     layoutScale, params.ptrPerTokenScale,
205	                                      layoutPerTokenScale, params.ptrD, layoutD};
206	
207	        blockScheduler.Update(params.problemShape, L1TileShape::ToCoordMN());
208	        blockEpilogue.UpdateParams(epilogueParams);
209	        uint32_t coreLoops = blockScheduler.GetCoreLoops();
210	
211	        GemmCoord blockShapeMNK = L1TileShape::ToCoord();
212	        for (uint32_t loopIdx = coreIdx; loopIdx < coreLoops; loopIdx += coreNum) {
213	            GemmCoord blockCoordMNK = blockScheduler.GetBlockCoord(loopIdx);
214	            GemmCoord actualBlockShapeMNK = blockScheduler.GetActualBlockShape(blockCoordMNK);
215	
216	            auto gmBlockC = gmC[layoutC.GetOffset(blockCoordMNK.GetCoordMN() * blockShapeMNK.GetCoordMN())];
217	            auto layoutBlockC = layoutC.GetTileLayout(actualBlockShapeMNK.GetCoordMN());
218	
219	            blockEpilogue(
220	                blockShapeMNK, blockCoordMNK, actualBlockShapeMNK, gmBlockC, layoutBlockC,
221	                MakeCallback(&aicFinishSync));
222	        }
223	
224	        AscendC::PipeBarrier<PIPE_ALL>();
225	    }
226	
227	private:
228	    static constexpr Arch::FlagID FLAG_AIC_FINISH_STORE = 0;
229	    static constexpr Arch::FlagID RV_FLAG_AIC_FINISH_STORE = 1;
230	    Arch::CrossCoreFlagWithReverse<> flagAicFinishStore{FLAG_AIC_FINISH_STORE, RV_FLAG_AIC_FINISH_STORE};
231	    Arch::Resource<ArchTag> resource;
232	};
233	
234	} // namespace Catlass::Gemm::Kernel
235	
236	#endif // CATLASS_GEMM_KERNEL_QUANT_MATMUL_HPP
