11	#ifndef CATLASS_GEMM_KERNEL_FP8_MATMUL_HPP
12	#define CATLASS_GEMM_KERNEL_FP8_MATMUL_HPP
13	
14	#include "catlass/catlass.hpp"
15	#include "catlass/arch/resource.hpp"
16	#include "catlass/coord.hpp"
17	#include "catlass/layout/layout.hpp"
18	#include "catlass/gemm_coord.hpp"
19	#include "catlass/matrix_coord.hpp"
20	#include "catlass/arch/cross_core_sync.hpp"
21	
22	namespace Catlass::Gemm::Kernel {
23	
24	template <
25	    class BlockMmad_, class BlockEpilogue_, class BlockScheduler_, uint32_t mScalar, uint32_t nScalar,
26	    uint32_t splitkLength>
27	class FP8Matmul {
28	public:
29	    using BlockMmad = BlockMmad_;
30	    using ArchTag = typename BlockMmad::ArchTag;
31	    using L1TileShape = typename BlockMmad::L1TileShape;
32	    using ElementA = typename BlockMmad::ElementA;
33	    using ElementA_ = typename std::conditional_t<
34	        std::is_same_v<typename BlockMmad::PrologueA, void>, ElementA, typename BlockMmad::PrologueA::ElementSrc>;
35	    using LayoutA = typename BlockMmad::LayoutA;
36	    using LayoutA_ = typename std::conditional_t<
37	        std::is_same_v<typename BlockMmad::PrologueA, void>, LayoutA,
38	        typename BlockMmad::PrologueA::LayoutSrc>; // LayoutPrologueA
39	    using ElementB = typename BlockMmad::ElementB;
40	    using ElementB_ = typename std::conditional_t<
41	        std::is_same_v<typename BlockMmad::PrologueB, void>, ElementB, typename BlockMmad::PrologueB::ElementSrc>;
42	    using LayoutB = typename BlockMmad::LayoutB;
43	    using LayoutB_ = typename std::conditional_t<
44	        std::is_same_v<typename BlockMmad::PrologueB, void>, LayoutB, typename BlockMmad::PrologueB::LayoutSrc>;
45	    using ElementC = typename BlockMmad::ElementC;
46	    using LayoutC = typename BlockMmad::LayoutC;
47	    using ElementAccumulator = typename BlockMmad::ElementAccumulator;
48	
49	    using MmadParams = typename BlockMmad_::Params;
50	    using BlockScheduler = BlockScheduler_;
51	
52	    /// Parameters structure
53	    struct Params {
54	        // Data members
55	        GemmCoord problemShape;
56	        GM_ADDR ptrA;
57	        LayoutA_ layoutA;
58	        GM_ADDR ptrB;
59	        LayoutB_ layoutB;
60	        GM_ADDR ptrC;
61	        LayoutC layoutC;
62	        GM_ADDR ptrWA;
63	        GM_ADDR ptrWB;
64	        GM_ADDR ptrWC;
65	        // half scalar;
66	        // half zeroPoint;
67	
68	        MmadParams mmadParams;
69	        // MMadParams: {prologueAParams, prologueBParams, mScalar, nScalar, splitkLength}
70	
71	        // Methods
72	        CATLASS_HOST_DEVICE
73	        Params()
74	        {}
75	
76	        CATLASS_HOST_DEVICE
77	        Params(
78	            GemmCoord const& problemShape_, GM_ADDR ptrA_, LayoutA layoutA_, GM_ADDR ptrB_, LayoutB layoutB_,
79	            GM_ADDR ptrC_, LayoutC layoutC_, GM_ADDR ptrWA_, GM_ADDR ptrWB_, GM_ADDR ptrWC_, MmadParams mmadParams_)
80	            : problemShape(problemShape_),
81	              ptrA(ptrA_),
82	              layoutA(layoutA_),
83	              ptrB(ptrB_),
84	              layoutB(layoutB_),
85	              ptrC(ptrC_),
86	              layoutC(layoutC_),
87	              ptrWA(ptrWA_),
88	              ptrWB(ptrWB_),
89	              ptrWC(ptrWC_),
90	              mmadParams(mmadParams_)
91	        {}
92	    };
93	
94	    struct Arguments {
95	        GemmCoord problemShape;
96	        uint32_t aicCoreNum;
97	        GM_ADDR ptrA;
98	        GM_ADDR ptrB;
99	        GM_ADDR ptrC;
100	        half scalar;
101	        half zeroPoint;
102	    };
103	
104	    static bool CanImplement(const Arguments& args)
105	    {
106	        return true;
107	    }
108	
109	    static size_t GetWorkspaceSize(const Arguments& args)
110	    {
111	        return GetSizeWA(args.aicCoreNum) + GetSizeWB(args.aicCoreNum) + GetSizeWC(args.aicCoreNum);
112	    }
113	
114	    static Params ToUnderlyingArguments(const Arguments& args, uint8_t* workspace)
115	    {
116	        LayoutA layoutA = LayoutA::template MakeLayout<ElementA>(args.problemShape.m(), args.problemShape.k());
117	        LayoutB layoutB = LayoutB::template MakeLayout<ElementB>(args.problemShape.k(), args.problemShape.n());
118	        LayoutC layoutC = LayoutC::template MakeLayout<ElementC>(args.problemShape.m(), args.problemShape.n());
119	
120	        // Malloc memory @[npu device]
121	        uint8_t* gmWA = nullptr;
122	        uint8_t* gmWB = nullptr;
123	        uint8_t* gmWC = nullptr;
124	        gmWA = workspace;
125	        workspace += GetSizeWA(args.aicCoreNum);
126	        gmWB = workspace;
127	        workspace += GetSizeWB(args.aicCoreNum);
128	        gmWC = workspace;
129	
130	        Params params{
131	            args.problemShape,
132	            args.ptrA,
133	            layoutA,
134	            args.ptrB,
135	            layoutB,
136	            args.ptrC,
137	            layoutC,
138	            gmWA,
139	            gmWB,
140	            gmWC,
141	            {{args.scalar, args.zeroPoint}, {args.scalar, args.zeroPoint}, mScalar, nScalar, splitkLength}};
142	        return params;
143	    }
144	
145	    // Methods
146	    CATLASS_DEVICE
147	    FP8Matmul()
148	    {
149	        flag0[0].id = flagID0;
150	        flag0[1].id = flagID1;
151	    }
152	
153	    /// Executes one GEMM
154	    template <int32_t CORE_TYPE = g_coreType>
155	    CATLASS_DEVICE __attribute__((always_inline)) void operator()(Params const& params);
156	
157	    template <>
158	    CATLASS_DEVICE void operator()<AscendC::AIV>(Params const& params)
159	    {
160	        BlockMmad blockMmad(resource, params.mmadParams);
161	        BlockScheduler blockScheduler(
162	            params.problemShape, MakeCoord((L1TileShape::M * mScalar), (L1TileShape::N * nScalar)));
163	
164	        AscendC::GlobalTensor<int8_t> gmA;
165	        gmA.SetGlobalBuffer((__gm__ int8_t*)params.ptrA);
166	        AscendC::GlobalTensor<half> gmWA;
167	        gmWA.SetGlobalBuffer((__gm__ half*)params.ptrWA);
168	
169	        AscendC::GlobalTensor<int8_t> gmB;
170	        gmB.SetGlobalBuffer((__gm__ int8_t*)params.ptrB);
171	        AscendC::GlobalTensor<half> gmWB;
172	        gmWB.SetGlobalBuffer((__gm__ half*)params.ptrWB);
173	
174	        AscendC::GlobalTensor<half> gmC;
175	        gmC.SetGlobalBuffer((__gm__ half*)params.ptrC);
176	        AscendC::GlobalTensor<float> gmWC;
177	        gmWC.SetGlobalBuffer((__gm__ float*)params.ptrWC);
178	
179	        uint32_t coreLoops = blockScheduler.GetCoreLoops();
180	        for (uint32_t loopIdx = AscendC::GetBlockIdx() / AIVPERCORE; loopIdx < coreLoops;
181	             loopIdx += AscendC::GetBlockNum()) { // 一次for循环完成两个行块或者两个列块的反量化
182	            // 当前任务块信息
183	            GemmCoord blockCoord = blockScheduler.GetBlockCoord(loopIdx);
184	            GemmCoord actualBlockShape = blockScheduler.GetActualBlockShape(blockCoord);
185	
186	            // 下一个任务块的信息
187	            GemmCoord nextBlockCoord;
188	            GemmCoord nextActualBlockShape;
189	            bool isFirstBlock = (loopIdx == (AscendC::GetBlockIdx() / AIVPERCORE));
190	            bool hasNextBlock = (loopIdx + AscendC::GetBlockNum() < coreLoops);
191	            if (hasNextBlock) {
192	                nextBlockCoord = blockScheduler.GetBlockCoord(loopIdx + AscendC::GetBlockNum());
193	                nextActualBlockShape = blockScheduler.GetActualBlockShape(nextBlockCoord);
194	            }
195	
196	            blockMmad.Prologue(
197	                gmWA, gmA, params.layoutA, gmWB, gmB, params.layoutB, gmC, gmWC, params.layoutC, blockCoord,
198	                nextBlockCoord, actualBlockShape, nextActualBlockShape, params.problemShape, isFirstBlock, hasNextBlock,
199	                bufferIndex);
200	        }
201	    }
202	
203	    template <>
204	    CATLASS_DEVICE void operator()<AscendC::AIC>(Params const& params)
205	    {
206	        BlockMmad blockMmad(resource, params.mmadParams);
207	        BlockScheduler blockScheduler(
208	            params.problemShape, MakeCoord((L1TileShape::M * mScalar), (L1TileShape::N * nScalar)));
