218	        for (uint32_t loopIdx = AscendC::GetBlockIdx(); loopIdx < coreLoops;
219	             loopIdx += AscendC::GetBlockNum()) { // 一次for循环完成一个大基本结果块(256,512)
220	            // Compute block location
221	            // 获取当前大基本结果块的左上角坐标以及实际大小
222	            GemmCoord blockCoord = blockScheduler.GetBlockCoord(loopIdx);
223	            GemmCoord actualBigBlockShape = blockScheduler.GetActualBlockShape(blockCoord);
224	
225	            blockMmad(gmWA, gmWB, gmWC, actualBigBlockShape, params.problemShape);
226	        }
227	    }
