26	template <class BlockMmad_, class BlockEpilogue_, class BlockScheduler_>
27	class W4A8Matmul {
28	public:
29	    using BlockMmad = BlockMmad_;
30	    using ArchTag = typename BlockMmad::ArchTag;
31	    using ElementA = typename BlockMmad::ElementA;
32	    using ElementPrologueB = typename BlockMmad::PrologueB::ElementSrc;
