44	    using BlockScheduler = BlockScheduler_;
45	
46	    /// Parameters structure
47	    struct Params {
48	        // Data members
49	        GemmCoord problemShape;
50	        GM_ADDR ptrA;
51	        LayoutA layoutA;
52	        GM_ADDR ptrPrologueB;
53	        LayoutPrologueB layoutPrologueB;
54	        GM_ADDR ptrC;
55	        LayoutC layoutC;
