59	        GM_ADDR ptrWorkspace;
60	
61	        // Methods
62	        CATLASS_HOST_DEVICE
63	        Params()
64	        {}
65	
66	        CATLASS_HOST_DEVICE
67	        Params(
68	            GemmCoord const& problemShape_, GM_ADDR ptrA_, LayoutA const& layoutA_, GM_ADDR ptrPrologueB_,
69	            LayoutPrologueB const& layoutPrologueB_, GM_ADDR ptrC_, LayoutC const& layoutC_,
70	            MmadParams const& mmadParams_, GM_ADDR ptrWorkspace_)
71	            : problemShape(problemShape_),
72	              ptrA(ptrA_),
73	              layoutA(layoutA_),
74	              ptrPrologueB(ptrPrologueB_),
75	              layoutPrologueB(layoutPrologueB_),
76	              ptrC(ptrC_),
77	              layoutC(layoutC_),
78	              mmadParams(mmadParams_),
79	              ptrWorkspace(ptrWorkspace_)
80	        {}
81	    };
82	
83	    struct Arguments {
84	        GemmCoord problemShape;
85	        GM_ADDR deviceA;
86	        LayoutA layoutA;
87	        GM_ADDR devicePrologueB;
88	        LayoutPrologueB layoutPrologueB;
89	        GM_ADDR deviceC;
90	        LayoutC layoutC;
91	        float scalar;
92	        uint32_t aicoreNum;
93	    };
94	
95	    static bool CanImplement(const Arguments& args)
96	    {
97	        return true;
98	    }
99	
100	    static size_t GetWorkspaceSize(Arguments const& args)
101	    {
102	        return BlockMmad::STAGES * L1TileShape::K * L1TileShape::N * sizeof(ElementB) * args.aicoreNum;
103	    }
104	
105	    static Params ToUnderlyingArguments(const Arguments& args, uint8_t* workspace)
106	    {
107	        Params params{
108	            args.problemShape,
109	            args.deviceA,
110	            args.layoutA,
111	            args.devicePrologueB,
112	            args.layoutPrologueB,
113	            args.deviceC,
114	            args.layoutC,
115	            {{}, {}, {args.scalar}},
116	            workspace};
