120	    // Methods
121	    CATLASS_DEVICE
122	    W4A8Matmul()
123	    {}
124	
125	    template <int32_t CORE_TYPE = g_coreType>
126	    CATLASS_DEVICE void operator()(Params const& params);
127	
128	    /// Executes matmul
129	    template <>
130	    CATLASS_DEVICE void operator()<AscendC::AIC>(Params const& params)
131	    {
132	        auto aicoreNum = AscendC::GetBlockNum();
133	        auto aicoreIdx = AscendC::GetBlockIdx();
134	
135	        BlockMmad blockMmad(resource, params.mmadParams);
136	
137	        GemmCoord blockShape = L1TileShape::ToCoord();
138	        BlockScheduler matmulBlockScheduler(params.problemShape, blockShape.GetCoordMN());
139	        uint32_t coreLoops = matmulBlockScheduler.GetCoreLoops();
140	
141	        // Load A from workspace
142	        AscendC::GlobalTensor<ElementA> gmA;
143	        gmA.SetGlobalBuffer(reinterpret_cast<__gm__ ElementA*>(params.ptrA));
144	
145	        LayoutB layoutBlockB{L1TileShape::K, L1TileShape::N};
146	        auto gmOffsetB = aicoreIdx * layoutBlockB.Capacity() * BlockMmad::STAGES;
147	        AscendC::GlobalTensor<ElementB> gmBlockB;
148	        gmBlockB.SetGlobalBuffer(reinterpret_cast<__gm__ ElementB*>(params.ptrWorkspace) + gmOffsetB);
149	
150	        AscendC::GlobalTensor<ElementC> gmC;
151	        gmC.SetGlobalBuffer(reinterpret_cast<__gm__ ElementC*>(params.ptrC));
152	
153	        for (uint32_t loopIdx = AscendC::GetBlockIdx(); loopIdx < coreLoops; loopIdx += AscendC::GetBlockNum()) {
154	            auto blockIdxCoord = matmulBlockScheduler.GetBlockCoord(loopIdx);
155	            auto actualBlockShape = matmulBlockScheduler.GetActualBlockShape(blockIdxCoord);
156	            GemmCoord offsetCoord = blockIdxCoord * blockShape;
157	
158	            auto gmBlockA = gmA[params.layoutA.GetOffset(offsetCoord.GetCoordMK())];
159	            auto layoutBlockA = params.layoutA.GetTileLayout(actualBlockShape.GetCoordMK());
160	            auto gmBlockC = gmC[params.layoutC.GetOffset(offsetCoord.GetCoordMN())];
161	            auto layoutBlockC = params.layoutC.GetTileLayout(actualBlockShape.GetCoordMN());
162	
163	            blockMmad(gmBlockA, layoutBlockA, gmBlockB, layoutBlockB, gmBlockC, layoutBlockC, actualBlockShape);
164	        }
165	    }
166	
167	    template <>
168	    CATLASS_DEVICE void operator()<AscendC::AIV>(Params const& params)
169	    {
170	        auto aicoreNum = AscendC::GetBlockNum();
171	        auto aicoreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
172	
173	        BlockMmad blockMmad(resource, params.mmadParams);
174	        BlockScheduler matmulBlockScheduler(params.problemShape, L1TileShape::ToCoordMN());
175	
176	        AscendC::GlobalTensor<ElementPrologueB> gmPrologueB;
177	        gmPrologueB.SetGlobalBuffer(reinterpret_cast<__gm__ ElementPrologueB*>(params.ptrPrologueB));
178	
179	        LayoutB layoutBlockB{L1TileShape::K, L1TileShape::N};
180	        auto gmOffsetB = aicoreIdx * layoutBlockB.Capacity() * BlockMmad::STAGES;
181	        AscendC::GlobalTensor<ElementB> gmBlockB;
182	        gmBlockB.SetGlobalBuffer(reinterpret_cast<__gm__ ElementB*>(params.ptrWorkspace) + gmOffsetB);
183	
184	        uint32_t coreLoops = matmulBlockScheduler.GetCoreLoops();
185	        for (uint32_t loopIdx = aicoreIdx; loopIdx < coreLoops; loopIdx += aicoreNum) {
186	            // Compute block location
187	            auto blockIdxCoord = matmulBlockScheduler.GetBlockCoord(loopIdx);
188	            auto actualBlockShape = matmulBlockScheduler.GetActualBlockShape(blockIdxCoord);
189	
190	            auto offsetCoordB = blockIdxCoord.GetCoordKN() * L1TileShape::ToCoordKN();
191	            auto gmBlockPrologueB = gmPrologueB[params.layoutPrologueB.GetOffset(offsetCoordB)];
192	            auto layoutBlockPrologueB = params.layoutPrologueB.GetTileLayout(actualBlockShape.GetCoordKN());
193	
194	            // Compute block-scoped matrix multiply-add
195	            blockMmad.Prologue(gmBlockPrologueB, layoutBlockPrologueB, gmBlockB, layoutBlockB, actualBlockShape);
196	        }
197	    }
198	
199	private:
200	    Arch::Resource<ArchTag> resource;
201	};
202	
203	} // namespace Catlass::Gemm::Kernel
204	
205	#endif // CATLASS_GEMM_KERNEL_W4A8_MATMUL_LOCAL_HPP
