51	
52	static const std::string kDataRoot = "examples/63_ascend950_dual_level_quant_mx_batch_matmul/data";
53	
54	template <typename T>
55	bool SaveResult(const std::string &filename, const std::vector<T> &data) {
56	    std::ofstream file(filename, std::ios::binary);
57	    if (!file) {
58	        return false;
59	    }
60	    const size_t dataSize = data.size() * sizeof(T);
61	    if (dataSize <= 0) {
62	        file.close();
63	        return true;
64	    }
65	
66	    std::vector<char> buffer(dataSize);
67	    std::memcpy(buffer.data(), data.data(), dataSize);
68	
69	    file.write(buffer.data(), dataSize);
70	    if (!file) {
71	        file.close();
72	        return false;
73	    }
74	
75	    file.close();
76	    return true;
77	}
78	
79	static void Run(const Options &options)
80	{
81	    aclrtStream stream{nullptr};
82	
83	    ACL_CHECK(aclInit(nullptr));
84	    ACL_CHECK(aclrtSetDevice(options.deviceId));
85	    ACL_CHECK(aclrtCreateStream(&stream));
86	
87	    uint32_t batchCount = options.problemCount;
88	    uint32_t m = options.problemShape.m();
89	    uint32_t n = options.problemShape.n();
90	    uint32_t k = options.problemShape.k();
91	    uint32_t mxScaleK = CeilDiv<MX_SCALE_GROUP_NUM>(k);
92	
93	    // ----- Type definitions -----
94	    using ElementInput = float16_t;
95	    using ElementA = float4_e2m1x2_t;
96	    using ElementB = float4_e2m1x2_t;
97	    using ElementMxScale = float8_e8m0_t;
98	    using ElementC = bfloat16_t;
99	
100	    using LayoutTagInputA = layout::RowMajor;
101	    using LayoutTagInputB = layout::RowMajor;
102	    using LayoutTagPhysicalB = layout::RowMajor;
103	    using LayoutTagA = layout::RowMajor;
104	    using LayoutTagB = layout::ColumnMajor;
105	    using LayoutTagC = layout::RowMajor;
106	
107	    // ----- Size calculations -----
108	    size_t lenInputA = static_cast<size_t>(m) * k * batchCount;
109	    size_t lenInputB = static_cast<size_t>(k) * n * batchCount;
110	    size_t sizeInputA = lenInputA * sizeof(ElementInput);
111	    size_t sizeInputB = lenInputB * sizeof(ElementInput);
112	
113	    size_t lenC = static_cast<size_t>(m) * n * batchCount;
114	    size_t sizeC = lenC * sizeof(ElementC);
115	
116	    uint32_t scaleA1K = CeilDiv<512>(k);
117	    uint32_t mxScaleAlignedK = RoundUp<2>(mxScaleK);
118	    size_t lenScaleA1 = static_cast<size_t>(m) * scaleA1K * batchCount;
119	    size_t lenScaleA2 = static_cast<size_t>(m) * mxScaleAlignedK * batchCount;
120	    size_t lenScaleB1 = static_cast<size_t>(scaleA1K) * n * batchCount;
121	    size_t lenScaleB2 = static_cast<size_t>(mxScaleAlignedK) * n * batchCount;
122	    size_t sizeScaleA1 = lenScaleA1 * sizeof(float);
123	    size_t sizeScaleA2 = lenScaleA2 * sizeof(ElementMxScale);
124	    size_t sizeScaleB1 = lenScaleB1 * sizeof(float);
125	    size_t sizeScaleB2 = lenScaleB2 * sizeof(ElementMxScale);
126	
127	    // ----- Host data -----
128	    std::vector<ElementInput> hostInputA(lenInputA);
129	    std::vector<ElementInput> hostInputB(lenInputB);
130	
131	    // ----- Device pointers -----
132	    uint8_t *deviceInputA{nullptr};
133	    uint8_t *deviceInputB{nullptr};
134	    uint8_t *deviceC{nullptr};
135	    uint8_t *deviceScaleA1{nullptr};
136	    uint8_t *deviceScaleA2{nullptr};
137	    uint8_t *deviceScaleB1{nullptr};
138	    uint8_t *deviceScaleB2{nullptr};
139	    uint8_t *deviceWorkspace{nullptr};
140	    size_t sizeWorkspace{0};
141	
142	    const auto cleanupAndFinalize = [&]() {
143	        if (deviceInputA) ACL_CHECK(aclrtFree(deviceInputA));
144	        if (deviceInputB) ACL_CHECK(aclrtFree(deviceInputB));
145	        if (deviceC) ACL_CHECK(aclrtFree(deviceC));
146	        if (deviceScaleA1) ACL_CHECK(aclrtFree(deviceScaleA1));
147	        if (deviceScaleA2) ACL_CHECK(aclrtFree(deviceScaleA2));
148	        if (deviceScaleB1) ACL_CHECK(aclrtFree(deviceScaleB1));
149	        if (deviceScaleB2) ACL_CHECK(aclrtFree(deviceScaleB2));
150	        if (sizeWorkspace > 0 && deviceWorkspace) ACL_CHECK(aclrtFree(deviceWorkspace));
151	        ACL_CHECK(aclrtDestroyStream(stream));
152	        ACL_CHECK(aclrtResetDevice(options.deviceId));
153	        ACL_CHECK(aclFinalize());
154	    };
155	
156	    // ----- Read input data -----
157	    std::string inputDir = kDataRoot + "/input";
158	    std::string goldenDir = kDataRoot + "/golden";
159	
160	    if (!ReadFile(inputDir + "/input_a.bin", hostInputA.data(), sizeInputA)) {
161	        cleanupAndFinalize();
162	        return;
163	    }
164	    if (!ReadFile(inputDir + "/input_b.bin", hostInputB.data(), sizeInputB)) {
165	        cleanupAndFinalize();
166	        return;
167	    }
168	
169	    // ----- Allocate device memory -----
170	    ACL_CHECK(aclrtMalloc(reinterpret_cast<void **>(&deviceInputA), sizeInputA, ACL_MEM_MALLOC_HUGE_FIRST));
171	    ACL_CHECK(aclrtMemcpy(deviceInputA, sizeInputA, hostInputA.data(), sizeInputA, ACL_MEMCPY_HOST_TO_DEVICE));
172	
173	    ACL_CHECK(aclrtMalloc(reinterpret_cast<void **>(&deviceInputB), sizeInputB, ACL_MEM_MALLOC_HUGE_FIRST));
174	    ACL_CHECK(aclrtMemcpy(deviceInputB, sizeInputB, hostInputB.data(), sizeInputB, ACL_MEMCPY_HOST_TO_DEVICE));
175	
176	    ACL_CHECK(aclrtMalloc(reinterpret_cast<void **>(&deviceC), sizeC, ACL_MEM_MALLOC_HUGE_FIRST));
177	    ACL_CHECK(aclrtMalloc(reinterpret_cast<void **>(&deviceScaleA1), sizeScaleA1, ACL_MEM_MALLOC_HUGE_FIRST));
178	    ACL_CHECK(aclrtMalloc(reinterpret_cast<void **>(&deviceScaleA2), sizeScaleA2, ACL_MEM_MALLOC_HUGE_FIRST));
179	    ACL_CHECK(aclrtMalloc(reinterpret_cast<void **>(&deviceScaleB1), sizeScaleB1, ACL_MEM_MALLOC_HUGE_FIRST));
180	    ACL_CHECK(aclrtMalloc(reinterpret_cast<void **>(&deviceScaleB2), sizeScaleB2, ACL_MEM_MALLOC_HUGE_FIRST));
181	
182	    // ----- Kernel template composition -----
183	    auto aicCoreNum = platform_ascendc::PlatformAscendCManager::GetInstance()->GetCoreNumAic();
184	
185	    using ArchTag = Arch::Ascend950;
186	    constexpr bool enableUnitFlag = true;
187	    using DispatchPolicy = Gemm::MmadMx<ArchTag, enableUnitFlag, 16>;
188	    using L1TileShape = Shape<Int<256>, Int<256>, Int<512>>;
189	    using L0TileShape = Shape<Int<256>, Int<256>, Int<256>>;
190	
191	    // AIV epilogue layouts and AIC matmul TLA layouts (single batch)
192	    auto layoutInputA = LayoutTagInputA::MakeLayout<ElementInput>(m, k);
193	    auto layoutInputB = LayoutTagInputB::MakeLayout<ElementInput>(n, k);
194	    auto layoutOutputA = LayoutTagA::MakeLayout<ElementA>(m, k);
195	    auto layoutOutputB = LayoutTagPhysicalB::MakeLayout<ElementB>(n, k);
196	    auto layoutScaleA1 = LayoutTagA::MakeLayout<float>(m, scaleA1K);
197	    auto layoutScaleA2 = LayoutTagA::MakeLayout<ElementMxScale>(m, mxScaleAlignedK);
198	    auto layoutScaleB1 = LayoutTagPhysicalB::MakeLayout<float>(n, scaleA1K);
199	    auto layoutScaleB2 = LayoutTagPhysicalB::MakeLayout<ElementMxScale>(n, mxScaleAlignedK);
200	    auto layoutQuantA = tla::MakeLayout<ElementA, LayoutTagA>(m, k);
201	    auto layoutQuantB = tla::MakeLayout<ElementB, LayoutTagB>(k, n);
202	    auto layoutMxScaleA = tla::MakeMxScaleLayout<ElementMxScale, LayoutTagA, false>(m, mxScaleK);
203	    auto layoutMxScaleB = tla::MakeMxScaleLayout<ElementMxScale, LayoutTagB, true>(mxScaleK, n);
204	    auto layoutC = tla::MakeLayout<ElementC, LayoutTagC>(m, n);
205	
206	    size_t sizeQuantAPerBatch = static_cast<size_t>(layoutOutputA.Capacity()) / 2;
207	    size_t sizeQuantBPerBatch = static_cast<size_t>(layoutOutputB.Capacity()) / 2;
208	    size_t sizeQuantA = sizeQuantAPerBatch * batchCount;
209	    size_t sizeQuantB = sizeQuantBPerBatch * batchCount;
210	
211	    // ----- AIC matmul -----
212	    using TileCopyMmad = Gemm::Tile::PackedMxTileCopyTla<
213	        ArchTag, ElementA, LayoutTagA, ElementB, LayoutTagB,
214	        ElementMxScale, decltype(layoutMxScaleA),
215	        ElementMxScale, decltype(layoutMxScaleB),
216	        ElementC, LayoutTagC, void>;
217	    using BlockMmad = Gemm::Block::BlockMmadTla<
218	        DispatchPolicy, L1TileShape, L0TileShape,
219	        ElementA, ElementB, ElementC, void, TileCopyMmad>;
220	
221	    // ----- AIV BlockQuant -----
222	    // block 不区分 A/B,只用 4 个 GemmType。
223	    constexpr uint32_t ubStages = 1;
224	    using EpilogueDispatchPolicy = Epilogue::EpilogueAscend950DualLevelQuantMx<ubStages>;
225	    using QuantSubTileShape = MatrixShape<128, 512>;
226	
227	    using InputType  = Gemm::GemmType<ElementInput,   layout::RowMajor>;
228	    using OutputType = Gemm::GemmType<ElementA,       layout::RowMajor>;
229	    using Scale1Type = Gemm::GemmType<float,          layout::RowMajor>;
230	    using Scale2Type = Gemm::GemmType<ElementMxScale, layout::RowMajor>;
231	
232	    using TileCopyQuant = Epilogue::Tile::TileCopyDualLevelQuantMx<
233	        ArchTag, InputType, OutputType, Scale1Type, Scale2Type>;
234	
235	    using BlockQuant = Epilogue::Block::BlockQuantDualLevelMx<
236	        EpilogueDispatchPolicy, QuantSubTileShape,
237	        InputType, OutputType, Scale1Type, Scale2Type,
238	        TileCopyQuant>;
239	
240	    // ===== P1-A: launch 核数策略 (NOT min(aicCoreNum, taskNum)) =====
241	    //
242	    // fused tile-level path:
243	    //   uint32_t taskNum = batchCount * CeilDiv(m, L1_TILE_M) * CeilDiv(n, L1_TILE_N);
244	    //   uint32_t aicCoreUsed = min(aicCoreNum, taskNum);   // ✗ 会卡住 AIV 并行度
245	    //
246	    // single-kernel path: 总是按物理 AIC 数 launch。
247	    // 空闲 AIC (loopIdx >= coreLoops) 自然跳过 matmul loop,无害退出;
248	    // 关键收益是 AIV 端 QuantAllScheduler 能用上全部 aicCoreNum * 2 个 AIV subblock。
249	    uint32_t aicCoreUsed = aicCoreNum;
250	
251	    // ----- Build kernel arguments & run -----
252	    // 根据 M vs N 选 BlockSwizzle 方向
253	    if (m > n) {
254	        using BlockScheduler = typename Gemm::Block::GemmIdentityBlockSwizzle<3, 0>;
255	        using DualLevelQuantKernel = Gemm::Kernel::DualLevelQuantMxBatchedMatmulTla<
256	            BlockMmad, BlockQuant, BlockScheduler, ElementInput>;
257	        using Adapter = Gemm::Device::DeviceGemm<DualLevelQuantKernel>;
258	
259	        typename DualLevelQuantKernel::Arguments arguments{
260	            batchCount, options.problemShape,
261	            deviceInputA, layoutInputA, deviceInputB, layoutInputB,
262	            deviceC, layoutC,
263	            deviceScaleA1, deviceScaleA2, layoutMxScaleA,
264	            deviceScaleB1, deviceScaleB2, layoutMxScaleB,
265	            layoutOutputA, layoutOutputB,
266	            layoutScaleA1, layoutScaleA2, layoutScaleB1, layoutScaleB2,
267	            layoutQuantA, layoutQuantB
268	        };
269	
270	        Adapter op;
271	        if (op.CanImplement(arguments) != Status::kSuccess) {
272	            std::cerr << "Cannot implement the arguments" << std::endl;
273	            cleanupAndFinalize();
274	            return;
275	        }
276	        sizeWorkspace = op.GetWorkspaceSize(arguments);
277	        if (sizeWorkspace > 0) {
278	            ACL_CHECK(aclrtMalloc(reinterpret_cast<void **>(&deviceWorkspace),
279	                                  sizeWorkspace, ACL_MEM_MALLOC_HUGE_FIRST));
280	        }
281	        op.Initialize(arguments, deviceWorkspace);
282	        op(stream, aicCoreUsed);
283	    } else {
284	        using BlockScheduler = typename Gemm::Block::GemmIdentityBlockSwizzle<3, 1>;
285	        using DualLevelQuantKernel = Gemm::Kernel::DualLevelQuantMxBatchedMatmulTla<
286	            BlockMmad, BlockQuant, BlockScheduler, ElementInput>;
287	        using Adapter = Gemm::Device::DeviceGemm<DualLevelQuantKernel>;
288	
289	        typename DualLevelQuantKernel::Arguments arguments{
290	            batchCount, options.problemShape,
291	            deviceInputA, layoutInputA, deviceInputB, layoutInputB,
292	            deviceC, layoutC,
293	            deviceScaleA1, deviceScaleA2, layoutMxScaleA,
294	            deviceScaleB1, deviceScaleB2, layoutMxScaleB,
295	            layoutOutputA, layoutOutputB,
296	            layoutScaleA1, layoutScaleA2, layoutScaleB1, layoutScaleB2,
297	            layoutQuantA, layoutQuantB
298	        };
299	
300	        Adapter op;
301	        if (op.CanImplement(arguments) != Status::kSuccess) {
302	            std::cerr << "Cannot implement the arguments" << std::endl;
303	            cleanupAndFinalize();
304	            return;
305	        }
306	        sizeWorkspace = op.GetWorkspaceSize(arguments);
307	        if (sizeWorkspace > 0) {
308	            ACL_CHECK(aclrtMalloc(reinterpret_cast<void **>(&deviceWorkspace),
309	                                  sizeWorkspace, ACL_MEM_MALLOC_HUGE_FIRST));
310	        }
311	        op.Initialize(arguments, deviceWorkspace);
312	        op(stream, aicCoreUsed);
313	    }
314	
315	    ACL_CHECK(aclrtSynchronizeStream(stream));
316	
317	    // ----- D2H: retrieve all outputs -----
318	    std::vector<bfloat16> hostC(lenC);
319	    ACL_CHECK(aclrtMemcpy(hostC.data(), sizeC, deviceC, sizeC, ACL_MEMCPY_DEVICE_TO_HOST));
320	
321	    std::vector<float> hostScaleA1(lenScaleA1);
322	    std::vector<uint8_t> hostScaleA2(sizeScaleA2);
323	    std::vector<float> hostScaleB1(lenScaleB1);
324	    std::vector<uint8_t> hostScaleB2(sizeScaleB2);
325	    ACL_CHECK(aclrtMemcpy(hostScaleA1.data(), sizeScaleA1, deviceScaleA1, sizeScaleA1, ACL_MEMCPY_DEVICE_TO_HOST));
326	    ACL_CHECK(aclrtMemcpy(hostScaleA2.data(), sizeScaleA2, deviceScaleA2, sizeScaleA2, ACL_MEMCPY_DEVICE_TO_HOST));
327	    ACL_CHECK(aclrtMemcpy(hostScaleB1.data(), sizeScaleB1, deviceScaleB1, sizeScaleB1, ACL_MEMCPY_DEVICE_TO_HOST));
328	    ACL_CHECK(aclrtMemcpy(hostScaleB2.data(), sizeScaleB2, deviceScaleB2, sizeScaleB2, ACL_MEMCPY_DEVICE_TO_HOST));
329	
330	    std::vector<uint8_t> hostQuantA(sizeQuantA);
331	    std::vector<uint8_t> hostQuantB(sizeQuantB);
332	    if (deviceWorkspace != nullptr && sizeWorkspace >= sizeQuantA + sizeQuantB) {
333	        ACL_CHECK(aclrtMemcpy(hostQuantA.data(), sizeQuantA,
334	                              deviceWorkspace, sizeQuantA, ACL_MEMCPY_DEVICE_TO_HOST));
335	        ACL_CHECK(aclrtMemcpy(hostQuantB.data(), sizeQuantB,
336	                              deviceWorkspace + sizeQuantA, sizeQuantB, ACL_MEMCPY_DEVICE_TO_HOST));
337	    }
338	
339	    std::string resultFileName = goldenDir + "/result.bin";
340	    SaveResult<bfloat16>(resultFileName, hostC);
341	    std::cout << "Result saved to: " << resultFileName << std::endl;
342	
343	    SaveResult<float>(goldenDir + "/scale_a1_result.bin", hostScaleA1);
344	    SaveResult<uint8_t>(goldenDir + "/scale_a2_result.bin", hostScaleA2);
345	    SaveResult<float>(goldenDir + "/scale_b1_result.bin", hostScaleB1);
346	    SaveResult<uint8_t>(goldenDir + "/scale_b2_result.bin", hostScaleB2);
347	    SaveResult<uint8_t>(goldenDir + "/quant_a_result.bin", hostQuantA);
348	    SaveResult<uint8_t>(goldenDir + "/quant_b_result.bin", hostQuantB);
349	
350	    // ----- Golden comparison -----
351	    std::vector<float> hostGolden(lenC);
352	    std::string goldenFileName = goldenDir + "/expected_data.bin";
353	    if (ReadFile(goldenFileName, hostGolden.data(), sizeof(float) * hostGolden.size())) {
354	        std::vector<uint64_t> errorIndices = golden::CompareData(hostC, hostGolden, k);
355	        if (errorIndices.empty()) {
356	            std::cout << "Compare success." << std::endl;
357	        } else {
358	            std::cerr << "Compare failed. Error count: " << errorIndices.size() << std::endl;
359	        }
360	    }
361	
362	    cleanupAndFinalize();
363	}
364	
365	int main(int argc, const char **argv)
366	{
367	    Options options;
368	    if (options.Parse(argc, argv) != 0) {
369	        return -1;
370	    }
371	    Run(options);
372	    return 0;
373	}
