39	constexpr uint32_t workspaceStages = 2;
40	
41	using Options = GemmOptions;
42	
43	static void Run(const Options& options)
44	{
45	    aclrtStream stream{nullptr};
46	    ACL_CHECK(aclInit(nullptr));
47	    ACL_CHECK(aclrtSetDevice(options.deviceId));
48	    ACL_CHECK(aclrtCreateStream(&stream));
49	
50	    auto aicCoreNum = platform_ascendc::PlatformAscendCManager::GetInstance()->GetCoreNumAic();
51	
