59	    TileCastFp8ToFp16Dequant(Arch::Resource<ArchTag>& resource, Params const& params_) : params(params_)
60	    {
61	        int64_t bufferOffset = 0;
62	        for (uint32_t i = 0; i < BUFFER_NUM; i++) {
63	            inputBuffer[i] = resource.ubBuf.template GetBufferByByte<ElementSrc>(bufferOffset * sizeof(ElementSrc));
64	            bufferOffset += COMPUTE_LENGTH;
65	        }
66	        for (uint32_t i = 0; i < BUFFER_NUM; i++) {
67	            outputBuffer[i] = (resource.ubBuf.template GetBufferByByte<ElementSrc>(bufferOffset * sizeof(ElementSrc)))
68	                                  .template ReinterpretCast<half>();
69	            bufferOffset += COMPUTE_LENGTH * 2;
70	        }
71	        for (uint32_t i = 0; i < BUFFER_NUM; i++) {
72	            workspace[i] = (resource.ubBuf.template GetBufferByByte<ElementSrc>(bufferOffset * sizeof(ElementSrc)))
73	                               .template ReinterpretCast<half>();
