79	    CATLASS_DEVICE
80	    void operator()(
81	        AscendC::GlobalTensor<ElementDst> gmDst, LayoutDst const& layoutDst, AscendC::GlobalTensor<ElementSrc> gmSrc,
82	        LayoutSrc const& layoutSrc, uint32_t& bufferIndex)
83	    {
84	        uint32_t tilesNum, tileLen, srcStride, dstStride;
85	        if constexpr (std::is_same_v<LayoutSrc, layout::RowMajor>) {
86	            tilesNum = layoutSrc.shape(0);
87	            tileLen = layoutSrc.shape(1);
88	            srcStride = layoutSrc.stride(0);
89	            dstStride = layoutDst.stride(0);
90	        } else if constexpr (std::is_same_v<LayoutSrc, layout::ColumnMajor>) {
91	            tilesNum = layoutSrc.shape(1);
92	            tileLen = layoutSrc.shape(0);
93	            srcStride = layoutSrc.stride(1);
94	            dstStride = layoutDst.stride(1);
95	        }
96	
97	        uint32_t tilesPerAiv = tilesNum / AscendC::GetSubBlockNum();
98	        uint32_t tilesRemain = tilesNum % AscendC::GetSubBlockNum();
99	        if (AscendC::GetSubBlockIdx() < tilesRemain) {
100	            tilesPerAiv++;
101	        }
102	
103	        uint64_t taskSrcOffset = AscendC::GetSubBlockIdx() * tilesPerAiv * srcStride;
104	        uint64_t taskDstOffset = AscendC::GetSubBlockIdx() * tilesPerAiv * dstStride;
105	        if (AscendC::GetSubBlockIdx() >= tilesRemain) {
106	            taskSrcOffset += tilesRemain * srcStride;
107	            taskDstOffset += tilesRemain * dstStride;
108	        }
109	
110	        uint32_t totalLoops = 0;
111	        uint32_t loopsPerTile, tilesInALoop;
112	        uint32_t tileLenRoundFp8 = RoundUp<Alignment, uint32_t>(tileLen);
113	        if (tileLenRoundFp8 > COMPUTE_LENGTH / 2) {
114	            // One signle tile length is bigger than COMPUTE_LENGTH, which should be clipped.
115	            loopsPerTile = CeilDiv(tileLen, COMPUTE_LENGTH);
116	            totalLoops = tilesPerAiv * loopsPerTile;
117	        } else if (tileLenRoundFp8 != 0) {
118	            // COMPUTE_LENGTH is bigger than tile length, such that more than one tiles can be arranged together.
119	            tilesInALoop = COMPUTE_LENGTH / tileLenRoundFp8;
120	            totalLoops = CeilDiv(tilesPerAiv, tilesInALoop);
121	        } // tileLenRoundFp8 == 0 --> totalLoops = 0
122	
123	        uint32_t tileTailLen = tileLen % COMPUTE_LENGTH;
124	        uint64_t srcProcessOffset, dstProcessOffset;
125	        uint32_t loadLen = COMPUTE_LENGTH, storeLen, loadRepeat = 1, storeRepeat = 1;
126	        // uint32_t srcLoadStride = srcStride, dstLoadStride = tileLenRoundFp8,
127	        //         srcStoreStride = tileLenRoundFp8, dstStoreStride = dstStride;
128	        for (int ldx = 0; ldx < totalLoops; ldx++) {
129	            // Dynamic compute length
130	            if (tileLenRoundFp8 > COMPUTE_LENGTH / 2) {
131	                uint32_t fullTileRounds = ldx / loopsPerTile;
132	                uint32_t residueTileRounds = ldx % loopsPerTile;
133	                srcProcessOffset = taskSrcOffset + fullTileRounds * srcStride + residueTileRounds * COMPUTE_LENGTH;
134	                dstProcessOffset = taskDstOffset + fullTileRounds * dstStride + residueTileRounds * COMPUTE_LENGTH;
135	
136	                if ((residueTileRounds == loopsPerTile - 1) && (tileTailLen != 0)) {
137	                    loadLen = tileTailLen;
138	                }
139	            } else {
140	                uint32_t fullTileRounds = ldx * tilesInALoop;
141	                srcProcessOffset = taskSrcOffset + fullTileRounds * srcStride;
142	                dstProcessOffset = taskDstOffset + fullTileRounds * dstStride;
143	
144	                loadLen = tileLen;
145	                storeLen = tileLen;
146	                loadRepeat = tilesInALoop;
147	                storeRepeat = tilesInALoop;
148	
149	                if ((ldx == totalLoops - 1) && (tilesPerAiv % tilesInALoop != 0)) {
150	                    loadRepeat = tilesPerAiv % tilesInALoop;
151	                    storeRepeat = loadRepeat;
152	                }
153	            }
154	            // uint32_t srcLoadStride = srcStride;
155	            // uint32_t dstLoadStride = tileLenRoundFp8;
156	            // uint32_t srcStoreStride = tileLenRoundFp8;
157	
158	            // GM -> UB
159	            AscendC::DataCopyExtParams dataCopyParamsIn(
160	                loadRepeat, loadLen * sizeof(ElementSrc),
161	                (srcStride - loadLen) * sizeof(ElementSrc), //
162	                (tileLenRoundFp8 - loadLen) * sizeof(ElementSrc) / BYTE_PER_BLK, 0);
163	            AscendC::DataCopyPadExtParams<ElementSrc> padParams(false, 0, 0, 0);
164	
165	            AscendC::WaitFlag<AscendC::HardEvent::V_MTE2>(EventIdBuffer[bufferIndex]);
166	            AscendC::DataCopyPad(inputBuffer[bufferIndex], gmSrc[srcProcessOffset], dataCopyParamsIn, padParams);
167	
168	            AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(EventIdBuffer[bufferIndex]);
169	            AscendC::WaitFlag<AscendC::HardEvent::MTE2_V>(EventIdBuffer[bufferIndex]);
170	            AscendC::WaitFlag<AscendC::HardEvent::MTE3_V>(EventIdBuffer[bufferIndex]);
171	
172	            Dequant(
173	                inputBuffer[bufferIndex], outputBuffer[bufferIndex], value_vector1, value_vector2,
174	                workspace[bufferIndex]);
175	            AscendC::SetFlag<AscendC::HardEvent::V_MTE3>(EventIdBuffer[bufferIndex]);
176	            AscendC::WaitFlag<AscendC::HardEvent::V_MTE3>(EventIdBuffer[bufferIndex]);
177	            AscendC::SetFlag<AscendC::HardEvent::V_MTE2>(EventIdBuffer[bufferIndex]);
178	
179	            AscendC::DataCopyExtParams dataCopyParams(
180	                storeRepeat, storeLen * sizeof(ElementDst),
181	                (tileLenRoundFp8 - storeLen) * sizeof(ElementDst) / BYTE_PER_C0,
182	                (dstStride - storeLen) * sizeof(ElementDst), 0);
183	            AscendC::DataCopyPad(gmDst[dstProcessOffset], outputBuffer[bufferIndex], dataCopyParams);
184	            AscendC::SetFlag<AscendC::HardEvent::MTE3_V>(EventIdBuffer[bufferIndex]);
185	            bufferIndex = (bufferIndex + 1) % BUFFER_NUM;
186	        }
187	    }
