189	    /*
190	     * DATAFLOW: gmSrc<float> -> ubInTensor -> ubOutTensor -> gmDst
191	     */
192	    CATLASS_DEVICE
193	    void EpCastFp32ToFp16(
194	        AscendC::GlobalTensor<half> gmDst, LayoutRowMajor layoutDst, AscendC::GlobalTensor<float> gmSrc,
195	        LayoutRowMajor layoutSrc)
196	    {
197	        AscendC::LocalTensor<float> ubInTensor[BUFFER_NUM];
198	        AscendC::LocalTensor<half> ubOutTensor[BUFFER_NUM];
199	
200	        Arch::Resource<ArchTag> resource;
201	        int64_t bufferOffset = 0;
202	        const int64_t CAST_LENGTH = 32 * 1024 / sizeof(half); // 一次处理16K个数据
203	        for (int i = 0; i < BUFFER_NUM; i++) {
204	            ubInTensor[i] = resource.ubBuf.template GetBufferByByte<float>(bufferOffset);
205	            bufferOffset += CAST_LENGTH * 4; // float 4字节
206	        }
207	        for (int i = 0; i < BUFFER_NUM; i++) {
208	            ubOutTensor[i] = resource.ubBuf.template GetBufferByByte<half>(bufferOffset);
209	            bufferOffset += CAST_LENGTH * 2; // half 2字节
210	        }
211	
212	        uint32_t tilesNum, tileLen, srcStride, dstStride;
213	        tilesNum = layoutSrc.shape(0);
214	        tileLen = layoutSrc.shape(1);
215	        srcStride = layoutSrc.stride(0);
216	        dstStride = layoutDst.stride(0); // Always RowMajor
217	
218	        uint32_t tilesPerAiv = tilesNum / AscendC::GetSubBlockNum();
219	        uint32_t tilesRemain = tilesNum % AscendC::GetSubBlockNum();
220	        if (AscendC::GetSubBlockIdx() < tilesRemain) {
221	            tilesPerAiv++;
222	        }
223	
224	        uint64_t taskSrcOffset = AscendC::GetSubBlockIdx() * tilesPerAiv * srcStride;
225	        uint64_t taskDstOffset = AscendC::GetSubBlockIdx() * tilesPerAiv * dstStride;
226	        if (AscendC::GetSubBlockIdx() >= tilesRemain) {
227	            taskSrcOffset += tilesRemain * srcStride;
228	            taskDstOffset += tilesRemain * dstStride;
229	        }
230	
231	        uint32_t totalLoops = 0;
232	        uint32_t loopsPerTile, tilesInALoop;
233	        uint32_t tileLenRoundFp8 = RoundUp<Alignment, uint32_t>(tileLen);
234	        if (tileLenRoundFp8 > COMPUTE_LENGTH / 2) {
235	            // One signle tile length is bigger than COMPUTE_LENGTH, which should be clipped.
236	            loopsPerTile = CeilDiv(tileLen, COMPUTE_LENGTH);
237	            totalLoops = tilesPerAiv * loopsPerTile;
238	        } else if (tileLenRoundFp8 != 0) {
239	            // COMPUTE_LENGTH is bigger than tile length, such that more than one tiles can be arranged together.
240	            tilesInALoop = COMPUTE_LENGTH / tileLenRoundFp8;
241	            totalLoops = CeilDiv(tilesPerAiv, tilesInALoop);
242	        } // tileLenRoundFp8 == 0 --> totalLoops = 0
243	
244	        uint32_t tileTailLen = tileLen % COMPUTE_LENGTH;
245	        uint64_t srcProcessOffset, dstProcessOffset;
246	        uint32_t loadLen = COMPUTE_LENGTH, storeLen, loadRepeat = 1, storeRepeat = 1;
247	        // uint32_t srcLoadStride = srcStride, dstLoadStride = tileLenRoundFp8,
248	        //         srcStoreStride = tileLenRoundFp8, dstStoreStride = dstStride;
249	        for (int ldx = 0; ldx < totalLoops; ldx++) {
250	            // Dynamic compute length
251	            if (tileLenRoundFp8 > COMPUTE_LENGTH / 2) {
252	                uint32_t fullTileRounds = ldx / loopsPerTile;
253	                uint32_t residueTileRounds = ldx % loopsPerTile;
254	                srcProcessOffset = taskSrcOffset + fullTileRounds * srcStride + residueTileRounds * COMPUTE_LENGTH;
255	                dstProcessOffset = taskDstOffset + fullTileRounds * dstStride + residueTileRounds * COMPUTE_LENGTH;
256	
257	                if ((residueTileRounds == loopsPerTile - 1) && (tileTailLen != 0)) {
258	                    loadLen = tileTailLen;
259	                }
260	            } else {
261	                uint32_t fullTileRounds = ldx * tilesInALoop;
262	                srcProcessOffset = taskSrcOffset + fullTileRounds * srcStride;
263	                dstProcessOffset = taskDstOffset + fullTileRounds * dstStride;
264	
265	                loadLen = tileLen;
266	                storeLen = tileLen;
267	                loadRepeat = tilesInALoop;
268	                storeRepeat = tilesInALoop;
269	
270	                if ((ldx == totalLoops - 1) && (tilesPerAiv % tilesInALoop != 0)) {
271	                    loadRepeat = tilesPerAiv % tilesInALoop;
272	                    storeRepeat = loadRepeat;
273	                }
274	            }
275	
276	            // copy GM -> UB <fp32>
277	            AscendC::WaitFlag<AscendC::HardEvent::V_MTE2>(EventIdBufferForCast[bufferIndexForCast]);
278	            AscendC::DataCopyExtParams dataCopyParamsIn(
279	                loadRepeat,
280	                loadLen * sizeof(float), // float loaded
281	                (srcStride - loadLen) * sizeof(float), (tileLenRoundFp8 - loadLen) * sizeof(float) / BYTE_PER_BLK, 0);
282	            AscendC::DataCopyPadExtParams<float> padParams(false, 0, 0, 0);
283	            AscendC::DataCopyPad(ubInTensor[bufferIndexForCast], gmSrc[srcProcessOffset], dataCopyParamsIn, padParams);
284	            // Begin casting ...
285	            AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(EventIdBufferForCast[bufferIndexForCast]);
286	            AscendC::WaitFlag<AscendC::HardEvent::MTE2_V>(EventIdBufferForCast[bufferIndexForCast]);
287	            AscendC::WaitFlag<AscendC::HardEvent::MTE3_V>(EventIdBufferForCast[bufferIndexForCast]);
288	            AscendC::Cast(
289	                ubOutTensor[bufferIndexForCast], ubInTensor[bufferIndexForCast], AscendC::RoundMode::CAST_RINT,
290	                CAST_LENGTH);
291	            AscendC::SetFlag<AscendC::HardEvent::V_MTE3>(EventIdBufferForCast[bufferIndexForCast]);
292	            AscendC::WaitFlag<AscendC::HardEvent::V_MTE3>(EventIdBufferForCast[bufferIndexForCast]);
293	            AscendC::SetFlag<AscendC::HardEvent::V_MTE2>(EventIdBufferForCast[bufferIndexForCast]);
294	            // End casting ...
295	
296	            AscendC::DataCopyExtParams dataCopyParams(
297	                storeRepeat, storeLen * sizeof(half), (tileLenRoundFp8 - storeLen) * sizeof(half) / BYTE_PER_C0,
298	                (dstStride - storeLen) * sizeof(half), 0);
299	            AscendC::DataCopyPad(gmDst[dstProcessOffset], ubOutTensor[bufferIndexForCast], dataCopyParams);
300	            AscendC::SetFlag<AscendC::HardEvent::MTE3_V>(EventIdBufferForCast[bufferIndexForCast]);
301	            bufferIndexForCast = (bufferIndexForCast + 1) % BUFFER_NUM;
302	        }
303	    }
304	
305	private:
306	    CATLASS_DEVICE
307	    void InitLocalMaskVec(Arch::Resource<ArchTag>& resource, int64_t& bufferOffset)
308	    {
309	        int16_t value_uint = 0x4000;
310	        value_vector1 = (resource.ubBuf.template GetBufferByByte<ElementSrc>(bufferOffset * sizeof(ElementSrc)))
311	                            .template ReinterpretCast<int16_t>();
312	        bufferOffset += 256;
313	        AscendC::Duplicate<int16_t>(value_vector1, value_uint, 128);
314	        AscendC::PipeBarrier<PIPE_V>();
315	        // AscendC::PipeBarrier<PIPE_V>();
316	        value_uint = 0x3FFF;
317	        value_vector2 = (resource.ubBuf.template GetBufferByByte<ElementSrc>(bufferOffset * sizeof(ElementSrc)))
318	                            .template ReinterpretCast<int16_t>();
319	        bufferOffset += 256;
320	        AscendC::Duplicate<int16_t>(value_vector2, value_uint, 128);
321	        AscendC::PipeBarrier<PIPE_V>();
322	    }
323	
324	    CATLASS_DEVICE
325	    void Dequant(
326	        AscendC::LocalTensor<int8_t>& src, AscendC::LocalTensor<half>& dst,
327	        AscendC::LocalTensor<int16_t>& value_vector1, AscendC::LocalTensor<int16_t>& value_vector2,
328	        AscendC::LocalTensor<half>& workspace)
329	    {
330	        pipe_barrier(PIPE_V);
331	        uint32_t num = COMPUTE_LENGTH;
332	        num = (num + 128 - 1) / 128 * 128;
333	        AscendC::Cast<half, uint8_t>(
334	            dst.template ReinterpretCast<half>(), src.template ReinterpretCast<uint8_t>(),
335	            AscendC::RoundMode::CAST_NONE, num);
336	        pipe_barrier(PIPE_V);
337	
338	        AscendC::Adds<half>(dst, dst, 1024, num);
339	        pipe_barrier(PIPE_V);
340	
341	        AscendC::ShiftLeft<uint16_t>(
342	            dst.template ReinterpretCast<uint16_t>(), dst.template ReinterpretCast<uint16_t>(), 7, num);
343	        pipe_barrier(PIPE_V);
344	
345	        uint64_t mask = 128;
346	        AscendC::And<int16_t>(
347	            workspace.template ReinterpretCast<int16_t>(), dst.template ReinterpretCast<int16_t>(), value_vector1, mask,
348	            num / 128, {1, 1, 1, 8, 8, 0});
349	        pipe_barrier(PIPE_V);
350	
351	        AscendC::ShiftLeft<uint16_t>(
352	            workspace.template ReinterpretCast<uint16_t>(), workspace.template ReinterpretCast<uint16_t>(), 1, num);
353	        pipe_barrier(PIPE_V);
354	
355	        AscendC::And<int16_t>(
356	            dst.template ReinterpretCast<int16_t>(), dst.template ReinterpretCast<int16_t>(), value_vector2, mask,
357	            num / 128, {1, 1, 1, 8, 8, 0});
358	        pipe_barrier(PIPE_V);
359	
360	        AscendC::Or<int16_t>(
361	            dst.template ReinterpretCast<int16_t>(), dst.template ReinterpretCast<int16_t>(),
362	            workspace.template ReinterpretCast<int16_t>(), num);
363	        pipe_barrier(PIPE_V);
364	
365	        AscendC::Muls<half>(dst.template ReinterpretCast<half>(), dst.template ReinterpretCast<half>(), 1 << 8, num);
366	        pipe_barrier(PIPE_V);
367	
368	        AscendC::Adds(dst, dst, params.zeroPoint, num);
369	        pipe_barrier(PIPE_V);
370	
371	        AscendC::Muls(dst, dst, params.scalar, num);
372	        pipe_barrier(PIPE_V);
373	    }
374	
375	private:
376	    static const uint32_t BUFFER_NUM = 2;
377	    AscendC::LocalTensor<int8_t> inputBuffer[BUFFER_NUM];
378	    AscendC::LocalTensor<int16_t> value_vector1;
379	    AscendC::LocalTensor<int16_t> value_vector2;
380	    AscendC::LocalTensor<half> outputBuffer[BUFFER_NUM];
381	    AscendC::LocalTensor<half> workspace[BUFFER_NUM];
382	    AscendC::TEventID EventIdBuffer[BUFFER_NUM] = {EVENT_ID0, EVENT_ID1};
383	    AscendC::TEventID EventIdBufferForCast[BUFFER_NUM] = {EVENT_ID2, EVENT_ID3};
384	    uint32_t bufferIndexForCast{0};
385	
386	    Params params;
387	};
388	
389	} // namespace Catlass::Gemm::Tile
390	
391	#endif // CATLASS_GEMM_TILE_ATLASA2_CAST_FP8_TO_FP16_HPP
