11	#ifndef CATLASS_GEMM_TILE_ATLASA2_CAST_INT4_TO_INT8_HPP
12	#define CATLASS_GEMM_TILE_ATLASA2_CAST_INT4_TO_INT8_HPP
13	
14	#include "catlass/catlass.hpp"
15	#include "catlass/arch/resource.hpp"
16	#include "catlass/coord.hpp"
17	#include "catlass/gemm_coord.hpp"
18	#include "catlass/gemm/dispatch_policy.hpp"
19	#include "catlass/gemm/helper.hpp"
20	
21	namespace Catlass::Gemm::Tile {
22	
23	template <
24	    class ArchTag, class SrcType_, class DstType_,
25	    // Length of the compute elements
26	    uint32_t COMPUTE_LEN_, uint32_t STAGES = 2>
27	struct TileCastInt4ToInt8 {
28	    using ElementSrc = typename SrcType_::Element;
29	    using ElementDst = typename DstType_::Element;
30	    using LayoutSrc = typename SrcType_::Layout;
31	    using LayoutDst = typename DstType_::Layout;
32	
33	    static constexpr uint32_t ELE_NUM_PER_BLK_INT8 = BYTE_PER_BLK / sizeof(ElementDst);
34	    static constexpr uint32_t ELE_NUM_PER_BLK_INT4 = BYTE_PER_BLK / sizeof(ElementDst) * 2;
35	
36	    static_assert(sizeof(ElementSrc) == sizeof(ElementDst), "Error: Src and Dst element sizes are equal (forbidden)");
37	
38	    static_assert(
39	        std::is_same_v<LayoutSrc, layout::RowMajor> || std::is_same_v<LayoutSrc, layout::ColumnMajor>,
40	        "Unsupported layout, only can be RowMajor, ColumnMajor or RowMajorInt4 or ColumnMajorInt4");
41	
42	    static constexpr uint32_t COMPUTE_LEN = COMPUTE_LEN_;
43	    static_assert(COMPUTE_LEN <= 24 * 1024, "COMPUTE_LEN cannot exceed 24 * 1024");
44	
45	    struct Params {};
46	
47	    /// Construct
48	    CATLASS_DEVICE
49	    TileCastInt4ToInt8(Arch::Resource<ArchTag> const& resource, Params const& params)
50	    {
51	        if constexpr (g_coreType == AscendC::AIV) {
52	            uint32_t ubOffset = 0;
53	            uint32_t ubInSize = COMPUTE_LEN * sizeof(int8_t) / 2;
54	            uint32_t ubOutSize = COMPUTE_LEN * sizeof(ElementDst);
55	            uint32_t ubWorkspaceSize = COMPUTE_LEN * sizeof(half);
56	            // Init buffers
57	            for (uint32_t i = 0; i < STAGES; i++) {
58	                ubInTensorList[i] = resource.ubBuf.template GetBufferByByte<ElementSrc>(ubOffset);
59	                ubOffset += ubInSize;
60	                ubOutTensorList[i] = resource.ubBuf.template GetBufferByByte<ElementDst>(ubOffset);
61	                ubOffset += ubOutSize;
62	                ubWorkspaceList[i] = resource.ubBuf.template GetBufferByByte<half>(ubOffset);
63	                ubOffset += ubWorkspaceSize;
64	
65	                ubEventList[i] = i;
66	                AscendC::SetFlag<AscendC::HardEvent::V_MTE2>(ubEventList[i]);
67	                AscendC::SetFlag<AscendC::HardEvent::MTE3_V>(ubEventList[i]);
68	            }
69	        }
70	    }
71	
72	    /// Destructor
73	    CATLASS_DEVICE
74	    ~TileCastInt4ToInt8()
75	    {
76	        if constexpr (g_coreType == AscendC::AIV) {
77	            for (uint32_t i = 0; i < STAGES; i++) {
78	                AscendC::WaitFlag<AscendC::HardEvent::V_MTE2>(ubEventList[i]);
79	                AscendC::WaitFlag<AscendC::HardEvent::MTE3_V>(ubEventList[i]);
80	            }
81	        }
82	    }
83	
84	    CATLASS_DEVICE
85	    void operator()(
86	        AscendC::GlobalTensor<ElementDst> const& gmDst, LayoutDst const& layoutDst,
87	        AscendC::GlobalTensor<ElementSrc> const& gmSrc, LayoutSrc const& layoutSrc)
88	    {
89	        uint32_t tilesNum = layoutSrc.shape(0);
90	        uint32_t tileLen = layoutSrc.shape(1);
91	        uint32_t tileLenRoundInt8 = RoundUp(layoutSrc.shape(1), ELE_NUM_PER_BLK_INT8);
92	        uint32_t tileLenRoundInt4 = RoundUp(layoutSrc.shape(1), ELE_NUM_PER_BLK_INT4);
93	        uint64_t tileStrideSrc = layoutSrc.stride(0);
94	        uint64_t tileStrideDst = layoutDst.stride(0);
95	        if constexpr (std::is_same_v<LayoutSrc, layout::ColumnMajor>) {
96	            tilesNum = layoutSrc.shape(1);
97	            tileLen = layoutSrc.shape(0);
98	            tileLenRoundInt8 = RoundUp(layoutSrc.shape(0), ELE_NUM_PER_BLK_INT8);
99	            tileLenRoundInt4 = RoundUp(layoutSrc.shape(0), ELE_NUM_PER_BLK_INT4);
100	            tileStrideSrc = layoutSrc.stride(1);
101	            tileStrideDst = layoutDst.stride(1);
102	        }
103	        uint32_t tilesPerAiv = tilesNum / AscendC::GetSubBlockNum();
104	        if (AscendC::GetSubBlockIdx() < (tilesNum % AscendC::GetSubBlockNum())) {
105	            tilesPerAiv++;
106	        }
107	        uint64_t taskOffsetSrc = AscendC::GetSubBlockIdx() * tilesPerAiv * tileStrideSrc;
108	        uint64_t taskOffsetDst = AscendC::GetSubBlockIdx() * tilesPerAiv * tileStrideDst;
109	        if (AscendC::GetSubBlockIdx() >= (tilesNum % AscendC::GetSubBlockNum())) {
110	            taskOffsetSrc += (tilesNum % AscendC::GetSubBlockNum()) * tileStrideSrc;
111	            taskOffsetDst += (tilesNum % AscendC::GetSubBlockNum()) * tileStrideDst;
112	        }
113	        uint32_t tilesPerLoop = 32;
114	        uint32_t loops = CeilDiv(tilesPerAiv, tilesPerLoop);
115	        uint32_t pingpong = 0;
116	        for (uint32_t loopIdx = 0; loopIdx < loops; loopIdx++) {
117	            uint32_t actualTiles = tilesPerLoop;
118	            if (loopIdx == loops - 1) {
119	                actualTiles = tilesPerAiv - loopIdx * tilesPerLoop;
120	            }
121	            uint64_t tileOffsetSrc = loopIdx * tilesPerLoop * tileStrideSrc;
122	            AscendC::DataCopyExtParams dataCopyParamsIn(
123	                actualTiles, (tileLen + 1) / 2 * sizeof(int8_t), (tileStrideSrc - tileLen) * sizeof(int8_t) / 2,
124	                (tileLenRoundInt4 - tileLen) / ELE_NUM_PER_BLK_INT4, 0);
125	            AscendC::DataCopyPadExtParams<ElementSrc> padParams(false, 0, 0, 0);
126	
127	            AscendC::WaitFlag<AscendC::HardEvent::V_MTE2>(ubEventList[pingpong]);
128	            AscendC::DataCopyPad(
129	                ubInTensorList[pingpong], gmSrc[taskOffsetSrc + tileOffsetSrc], dataCopyParamsIn, padParams);
130	
131	            AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(ubEventList[pingpong]);
132	            AscendC::WaitFlag<AscendC::HardEvent::MTE2_V>(ubEventList[pingpong]);
133	
134	            AscendC::WaitFlag<AscendC::HardEvent::MTE3_V>(ubEventList[pingpong]);
135	
136	            AscendC::Cast(
137	                ubWorkspaceList[pingpong], ubInTensorList[pingpong], AscendC::RoundMode::CAST_NONE,
138	                actualTiles * tileLenRoundInt4);
139	
140	            AscendC::PipeBarrier<PIPE_V>();
141	
142	            AscendC::SetFlag<AscendC::HardEvent::V_MTE2>(ubEventList[pingpong]);
143	
144	            AscendC::Cast(
145	                ubOutTensorList[pingpong], ubWorkspaceList[pingpong], AscendC::RoundMode::CAST_NONE,
146	                actualTiles * tileLenRoundInt4);
147	
148	            AscendC::SetFlag<AscendC::HardEvent::V_MTE3>(ubEventList[pingpong]);
149	            AscendC::WaitFlag<AscendC::HardEvent::V_MTE3>(ubEventList[pingpong]);
150	
151	            uint64_t tileOffsetDst = loopIdx * tilesPerLoop * tileStrideDst;
152	            AscendC::DataCopyExtParams dataCopyParamsOut(
153	                actualTiles, tileLen * sizeof(ElementDst), (tileLenRoundInt4 - tileLen) / ELE_NUM_PER_BLK_INT8,
154	                (tileStrideDst - tileLen) * sizeof(ElementDst), 0);
155	            AscendC::DataCopyPad(gmDst[taskOffsetDst + tileOffsetDst], ubOutTensorList[pingpong], dataCopyParamsOut);
156	            AscendC::SetFlag<AscendC::HardEvent::MTE3_V>(ubEventList[pingpong]);
157	
158	            pingpong = (pingpong + 1) % STAGES;
159	        }
160	    }
161	
162	protected:
163	    /// Data members
164	    AscendC::LocalTensor<ElementSrc> ubInTensorList[STAGES];
165	    AscendC::LocalTensor<ElementDst> ubOutTensorList[STAGES];
166	    AscendC::LocalTensor<half> ubWorkspaceList[STAGES];
167	
168	    int32_t ubEventList[STAGES];
169	};
170	
